import numpy as np
for c in ['green','purple','cyan']:
 p=np.load('/app/output/'+c+'_points.npy');p=p[p[:,2]>np.percentile(p[:,2],95)-.001][:,:2]
 best=None
 for t in np.linspace(0,np.pi/2,901):
  R=np.array([[np.cos(t),-np.sin(t)],[np.sin(t),np.cos(t)]]);v=p@R; lo=v.min(0);hi=v.max(0);area=np.prod(hi-lo)
  if best is None or area<best[0]:best=(area,t,(lo+hi)/2@R.T,hi-lo)
 print(c,best)
PY
